import{_ as e,o as n,a as p,c as a,b as c,d as l}from"./app.CIoiBgkh.js";const t="/ascendc.github.io/pr/6199/assets/data_vec_54.BjJTOCRo.png",o="/ascendc.github.io/pr/6199/assets/no_doublebuf_pipe.BVaIW7qj.png",i="/ascendc.github.io/pr/6199/assets/dbuf_pipe.BtzCrUff.png",T=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子性能优化","link":"/guide/operator_practice/simd_operator_optimization/simd_operator_optimization"},{"text":"流水编排","link":"/guide/operator_practice/simd_operator_optimization/pipeline_scheduling/pipeline_scheduling"},{"text":"开启Double Buffer","link":"/guide/operator_practice/simd_operator_optimization/pipeline_scheduling/enable_double_buffer"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_optimization/pipeline_scheduling/enable_double_buffer.md","filePath":"guide/operator_practice/simd_operator_optimization/pipeline_scheduling/enable_double_buffer.md","outlineHeaders":[{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明"},{"level":2,"title":"不同编程方式下的实现","slug":"不同编程方式下的实现","link":"#不同编程方式下的实现"},{"level":3,"title":"基于TPipe/TQue的编程方式","slug":"基于TPipe/TQue的编程方式","link":"#基于TPipe/TQue的编程方式"},{"level":3,"title":"基于指针的C语言编程方式","slug":"基于指针的C语言编程方式","link":"#基于指针的C语言编程方式"}],"lastUpdated":1789723573000}'),r={name:"guide/operator_practice/simd_operator_optimization/pipeline_scheduling/enable_double_buffer.md"},_={class:"markdown-body"},d={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},w={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.025ex"},xmlns:"http://www.w3.org/2000/svg",width:"0.817ex",height:"1.441ex",role:"img",focusable:"false",viewBox:"0 -626 361 637","aria-hidden":"true"};function u(f,s,h,g,m,b){return n(),p("div",null,[a("div",null,[a("article",_,[s[3]||(s[3]=c('<h1>开启Double Buffer<span id="ZH-CN_TOPIC_0000001893038945"></span></h1><p>【优先级】中</p><p>【描述】执行于AI Core上的指令队列主要包括如下几类：<a href="../../../technical_appendix/concepts_and_terms/glossary.html#p203923211517">Vector（矢量）</a>指令队列V、<a href="../../../technical_appendix/concepts_and_terms/glossary.html#p1038918214519">Cube（矩阵）</a>指令队列M、<a href="../../../technical_appendix/concepts_and_terms/glossary.html#p1739112219516">Scalar（标量）</a>指令队列S和搬运指令队列<a href="../../../technical_appendix/concepts_and_terms/glossary.html#p339019220518">Memory Transfer Engine 1（MTE1）</a>/<a href="../../../technical_appendix/concepts_and_terms/glossary.html#p53901325511">Memory Transfer Engine 2（MTE2）</a>/<a href="../../../technical_appendix/concepts_and_terms/glossary.html#p183901322511">Memory Transfer Engine 3（MTE3）</a>。不同指令队列间的相互独立性和可并行执行特性，是Double Buffer优化机制的基石。</p><p>以纯Vector计算为例，矢量计算前后的CopyIn、CopyOut过程使用搬运指令队列（MTE2/MTE3），Compute过程使用Vector指令队列（V）。不同指令队列可并行执行，意味着CopyIn、CopyOut过程和Compute过程可以并行。如下图所示，考虑一个完整的数据搬运和计算过程，CopyIn过程将数据从<a href="../../../technical_appendix/concepts_and_terms/glossary.html#p1439018225112">Global Memory（GM）</a>搬运到<a href="../../../technical_appendix/concepts_and_terms/glossary.html#p193901420518">Local Memory（LM）</a>，Vector计算单元完成Compute计算后，经过CopyOut过程将计算结果搬回GM。</p><p><strong>图1</strong> 数据搬运与Vector计算过程<span id="fig_data_vector_compute"></span><br><img src="'+t+'" alt title="数据搬运与Vector计算过程"></p><p><strong>图2</strong> 未开启Double Buffer的流水图<span id="fig_disable_double_buffer_pipeline"></span><br><img src="'+o+'" alt title="未开启Double Buffer的流水图"></p>',6)),a("p",null,[s[1]||(s[1]=l("在此过程中，数据搬运与Vector计算串行执行，Vector计算单元不可避免地存在资源闲置问题。假设CopyIn、Compute、CopyOut三个阶段的耗时均为",-1)),a("mjx-container",d,[(n(),p("svg",w,[...s[0]||(s[0]=[a("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[a("g",{"data-mml-node":"math"},[a("g",{"data-mml-node":"mi"},[a("path",{"data-c":"1D461",d:"M26 385Q19 392 19 395Q19 399 22 411T27 425Q29 430 36 430T87 431H140L159 511Q162 522 166 540T173 566T179 586T187 603T197 615T211 624T229 626Q247 625 254 615T261 596Q261 589 252 549T232 470L222 433Q222 431 272 431H323Q330 424 330 420Q330 398 317 385H210L174 240Q135 80 135 68Q135 26 162 26Q197 26 230 60T283 144Q285 150 288 151T303 153H307Q322 153 322 145Q322 142 319 133Q314 117 301 95T267 48T216 6T155 -11Q125 -11 98 4T59 56Q57 64 57 83V101L92 241Q127 382 128 383Q128 385 77 385H26Z",style:{"stroke-width":"3"}})])])],-1)])]))]),s[2]||(s[2]=l("，则Vector的利用率仅为三分之一，等待时间过长，Vector利用率严重不足。",-1))]),s[4]||(s[4]=c('<p>为减少Vector等待时间，Double Buffer为待处理数据准备Ping和Pong两组缓冲区。如下表所示，t0时，MTE2将数据块0的输入搬入Ping；t1时，MTE2将数据块1的输入搬入Pong，Vector同时使用Ping计算数据块0；t2时，MTE2将数据块2的输入搬入Ping，Vector使用Pong计算数据块1，MTE3同时从Ping搬出数据块0的结果。由此，数据搬入、Vector计算和数据搬出可以跨数据块并行执行，缓解Vector计算单元闲置问题。</p><p><strong>表1</strong> Ping/Pong Double Buffer的三个时间点</p><table><thead><tr><th>执行阶段</th><th>t0</th><th>t1</th><th>t2</th></tr></thead><tbody><tr><td>MTE2搬入</td><td>数据块0输入到Ping输入区</td><td>数据块1输入到Pong输入区</td><td>数据块2输入到Ping输入区</td></tr><tr><td>Vector计算</td><td>无</td><td>计算数据块0（Ping）</td><td>计算数据块1（Pong）</td></tr><tr><td>MTE3搬出</td><td>无</td><td>无</td><td>数据块0结果从Ping输出区搬出</td></tr></tbody></table><p>t2时，Ping中的输入区和输出区相互独立，因此数据块2搬入和数据块0搬出可以同时执行。</p><p>总体来说，Double Buffer是基于MTE指令队列与Vector指令队列的独立性和可并行性，通过将数据搬运与Vector计算并行执行以隐藏大部分的数据搬运时间，并降低Vector指令的等待时间，最终提高Vector单元的利用效率。开启Double Buffer后的整体流水如下图所示。</p><p><strong>图3</strong> 开启Double Buffer的流水图<span id="fig_enable_double_buffer_pipeline"></span><br><img src="'+i+`" alt title="开启Double Buffer的流水图"></p><h2 id="使用说明">使用说明<a class="header-anchor" href="#使用说明">​</a></h2><p>多数情况下，采用Double Buffer能有效提升Vector的利用率，缩减算子执行时间。然而，Double Buffer机制缓解Vector闲置问题，并不代表它总能带来明显的整体性能提升。例如：</p><ul><li>当数据搬运时间较短，而Vector计算时间较长时，由于数据搬运在整个计算过程中的时间占比较低，Double Buffer机制带来的性能收益会偏小。</li><li>当原始数据较小且Vector可以一次性完成所有数据量的计算时，无法形成跨数据块的流水重叠，额外的缓冲区和同步处理可能使效果适得其反。</li></ul><p>使用Double Buffer还需要满足以下条件：</p><ul><li>单核数据能够切分为至少两个数据块，使相邻数据块可以交替使用两组缓冲区。</li><li><a href="../../../technical_appendix/concepts_and_terms/glossary.html#p17392122195118">Unified Buffer（UB）</a>能够容纳两组输入和输出缓冲区以及算子所需的其他临时数据。</li><li>同一缓冲区的写入、读取和再次复用顺序能够通过相应编程方式的同步机制正确管理。</li><li>缓冲区地址和数据搬运长度满足目标产品及搬运接口的对齐要求，尾块按照实际数据长度进行处理。</li></ul><p>因此，Double Buffer的使用需综合考虑Vector算力、数据量、UB容量、数据块数量以及搬运与计算时间占比等因素。</p><h2 id="不同编程方式下的实现">不同编程方式下的实现<a class="header-anchor" href="#不同编程方式下的实现">​</a></h2><p>本文分别介绍基于<code>TPipe/TQue</code>的编程方式和基于指针的C语言编程方式。静态Tensor编程方式同样可以使用Double Buffer，但需要手动划分Ping/Pong缓冲区并管理同步事件，其实现和约束请参见<a href="../../../programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/static_tensor_programming.html#section121239188376">静态Tensor编程的流水优化</a>，本文不再单独展开。</p><h3 id="基于TPipe/TQue的编程方式">基于TPipe/TQue的编程方式<a class="header-anchor" href="#基于TPipe/TQue的编程方式">​</a></h3><p>采用<code>TPipe/TQue</code>管理资源时，通过在算子类的<code>Init</code>函数中调用<code>InitBuffer</code>初始化队列，并设置内存块数量，控制是否开启Double Buffer。<code>num</code>参数设置为1时，每个队列分配一个内存块，不开启Double Buffer；设置为2时，每个队列分配两个内存块，开启Double Buffer。</p><p>【反例】</p><p><code>InitBuffer</code>的<code>num</code>参数设置为1，输入和输出队列均只分配一个内存块，数据搬入、计算和数据搬出不能跨数据块重叠。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Init</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">src0Gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">src1Gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">dstGm</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">src0Global</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="p">)</span><span class="n">src0Gm</span><span class="p">);</span>
<span class="w">    </span><span class="n">src1Global</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="p">)</span><span class="n">src1Gm</span><span class="p">);</span>
<span class="w">    </span><span class="n">dstGlobal</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="p">)</span><span class="n">dstGm</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 不开启Double Buffer，占用的物理空间是1 * sizeSrc0 * sizeof(half)。</span>
<span class="w">    </span><span class="c1">// 三个InitBuffer执行后总空间为：</span>
<span class="w">    </span><span class="c1">// 1 * (sizeSrc0 * sizeof(half) + sizeSrc1 * sizeof(half) + sizeDst0 * sizeof(half))。</span>
<span class="w">    </span><span class="n">pipe</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">inQueueSrc0</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">sizeSrc0</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">    </span><span class="n">pipe</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">inQueueSrc1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">sizeSrc1</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">    </span><span class="n">pipe</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">outQueueDst</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">sizeDst0</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="p">}</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Process</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 需要round * 2次循环才能处理完数据。</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">round</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">index</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">CopyIn</span><span class="p">(</span><span class="n">index</span><span class="p">);</span>
<span class="w">        </span><span class="n">Compute</span><span class="p">();</span>
<span class="w">        </span><span class="n">CopyOut</span><span class="p">(</span><span class="n">index</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>【正例】</p><p>在<code>Init</code>函数初始化输入和输出队列时，将<code>InitBuffer</code>的<code>num</code>参数设置为2。<code>Process</code>函数按照数据块顺序调用<code>CopyIn</code>、<code>Compute</code>和<code>CopyOut</code>，队列根据内存块的入队、出队和释放顺序管理缓冲区复用及流水同步。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Init</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">src0Gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">src1Gm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">dstGm</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">src0Global</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="p">)</span><span class="n">src0Gm</span><span class="p">);</span>
<span class="w">    </span><span class="n">src1Global</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="p">)</span><span class="n">src1Gm</span><span class="p">);</span>
<span class="w">    </span><span class="n">dstGlobal</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="p">)</span><span class="n">dstGm</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// InitBuffer中使用2表示开启Double Buffer，占用的物理空间是2 * sizeSrc0 * sizeof(half)。</span>
<span class="w">    </span><span class="c1">// 三个InitBuffer执行后总空间为：</span>
<span class="w">    </span><span class="c1">// 2 * (sizeSrc0 * sizeof(half) + sizeSrc1 * sizeof(half) + sizeDst0 * sizeof(half))。</span>
<span class="w">    </span><span class="n">pipe</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">inQueueSrc0</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="n">sizeSrc0</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">    </span><span class="n">pipe</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">inQueueSrc1</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="n">sizeSrc1</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">    </span><span class="n">pipe</span><span class="p">.</span><span class="n">InitBuffer</span><span class="p">(</span><span class="n">outQueueDst</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="n">sizeDst0</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="p">}</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Process</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 开启Double Buffer的前提是循环次数大于等于2。</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">round</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">index</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">CopyIn</span><span class="p">(</span><span class="n">index</span><span class="p">);</span>
<span class="w">        </span><span class="n">Compute</span><span class="p">();</span>
<span class="w">        </span><span class="n">CopyOut</span><span class="p">(</span><span class="n">index</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>采用该方式时，需要注意以下事项：</p><ul><li><code>InitBuffer</code>应在算子类的<code>Init</code>函数中调用，三个参数依次表示队列、内存块数量和单个内存块的字节数。</li><li>开启Double Buffer后，输入和输出队列占用的UB空间增加为原来的两倍，需要重新计算单个数据块的长度和循环次数。</li><li><code>Process</code>中的循环次数取决于Tiling切分结果。上述<code>round</code>仅用于展示开启前后的代码位置，不能作为所有算子的固定计算方式。</li><li>如果尾块不能满足主块的Double Buffer切分条件，应单独处理尾块。</li></ul><p>完整的Tiling、队列初始化和主尾块处理方法请参见<a href="../../simd_operator_impl/vector_programming/double_buffer_scenario.html">Double Buffer场景</a>。</p><h3 id="基于指针的C语言编程方式">基于指针的C语言编程方式<a class="header-anchor" href="#基于指针的C语言编程方式">​</a></h3><p>采用基于指针的C语言编程方式时，Double Buffer不是单一开关，需要在Kernel中手动申请Ping和Pong两组UB缓冲区，根据数据块序号交替选择缓冲区，并使用<a href="../../../../api/SIMD-API/c_api/sync/intra_core_sync/asc_lock.html">asc_lock</a>和<a href="../../../../api/SIMD-API/c_api/sync/intra_core_sync/asc_unlock.html">asc_unlock</a>接口约束同一缓冲区的读取、写入和再次复用。</p><p>下面的代码省略了核间切分、搬运参数配置和Host侧逻辑，只保留Double Buffer所在的Kernel及其关键逻辑。完整的单缓冲区基线和Double Buffer实现请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/02_features/01_reg_vector_compute/00_add_double_buffer/README.md">融合向量计算Double Buffer样例</a>。<code>BLOCK_LENGTH</code>表示单个数据块的最大元素个数，<code>currentLength</code>表示当前数据块的实际元素个数。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_double_buffer</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">xGm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">yGm</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">zGm</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalElements</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc_init</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// 每组包含x、y、z三个Buffer，两组分别为Ping和Pong。</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">ubBuffer</span><span class="p">[</span><span class="n">BLOCK_LENGTH</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">6</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">xPing</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ubBuffer</span><span class="p">;</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">yPing</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">xPing</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">BLOCK_LENGTH</span><span class="p">;</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">zPing</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">yPing</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">BLOCK_LENGTH</span><span class="p">;</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">xPong</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">zPing</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">BLOCK_LENGTH</span><span class="p">;</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">yPong</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">xPong</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">BLOCK_LENGTH</span><span class="p">;</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">zPong</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">yPong</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">BLOCK_LENGTH</span><span class="p">;</span>

<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">totalElements</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">BLOCK_LENGTH</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">BLOCK_LENGTH</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">blockIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">blockIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">blockCount</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">blockIdx</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">BLOCK_LENGTH</span><span class="p">;</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">currentLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">totalElements</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">offset</span><span class="p">)</span><span class="w"> </span><span class="o">&gt;</span><span class="w"> </span><span class="n">BLOCK_LENGTH</span><span class="w"> </span><span class="o">?</span>
<span class="w">            </span><span class="nl">BLOCK_LENGTH</span><span class="w"> </span><span class="p">:</span><span class="w"> </span><span class="p">(</span><span class="n">totalElements</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">offset</span><span class="p">);</span>

<span class="w">        </span><span class="c1">// 偶数块使用Ping，奇数块使用Pong。</span>
<span class="w">        </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">inputMutexId</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
<span class="w">        </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">outputMutexId</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">inputMutexId</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">2</span><span class="p">);</span>
<span class="w">        </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">xLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="n">xPing</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">xPong</span><span class="p">;</span>
<span class="w">        </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">yLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="n">yPing</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">yPong</span><span class="p">;</span>
<span class="w">        </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">zLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">&amp;</span><span class="w"> </span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="n">zPing</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">zPong</span><span class="p">;</span>

<span class="w">        </span><span class="c1">// MTE2搬入当前块输入，输入Mutex保护同组x/y的再次写入。</span>
<span class="w">        </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">inputMutexId</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xGm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">currentLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yGm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">currentLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">inputMutexId</span><span class="p">);</span>

<span class="w">        </span><span class="c1">// Vector等待当前x/y就绪，并等待同组z可写。</span>
<span class="w">        </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">inputMutexId</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">outputMutexId</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_add</span><span class="p">(</span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">currentLength</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">inputMutexId</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">outputMutexId</span><span class="p">);</span>

<span class="w">        </span><span class="c1">// MTE3等待当前z计算完成后搬出。</span>
<span class="w">        </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">outputMutexId</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_copy_ub2gm_align</span><span class="p">(</span><span class="n">zGm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">currentLength</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">outputMutexId</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="c1">// Kernel退出前排空已提交但尚未完成的异步操作。</span>
<span class="w">    </span><span class="n">asc_sync_pipe</span><span class="p">(</span><span class="n">PIPE_ALL</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p><code>blockIdx</code>为0、1、2时，代码分别选择Ping、Pong、Ping。循环按照代码顺序提交数据搬入、计算和数据搬出操作，不同流水在满足同步依赖后异步执行，从而使相邻数据块形成重叠。</p><p>每组输入和输出缓冲区需要满足以下同步关系：</p><table><thead><tr><th>UB区域</th><th>生产者和消费者</th><th>需要保证的顺序</th><th>同步方式</th></tr></thead><tbody><tr><td>Ping/Pong <code>x/y</code></td><td>MTE2写入 -&gt; Vector读取</td><td>同组输入搬入完成后才能计算；下一次写入同组输入前，前一次读取必须结束。</td><td>使用该组的输入<code>mutex_id</code>。</td></tr><tr><td>Ping/Pong <code>z</code></td><td>Vector写入 -&gt; MTE3读取</td><td>计算完成后才能搬出结果。</td><td>使用该组的输出<code>mutex_id</code>。</td></tr><tr><td>Ping/Pong <code>z</code></td><td>MTE3读取 -&gt; 下一次Vector写入</td><td>前一个数据块的结果搬出完成后，才能复用同组输出缓冲区。</td><td>下一次Vector获取同一输出<code>mutex_id</code>时等待。</td></tr></tbody></table><p>MTE2向Ping的<code>x/y</code>搬入新数据时，MTE3可以同时从Ping的<code>z</code>搬出上一个数据块的结果，因为<code>x/y/z</code>是同一组中彼此独立的子缓冲区。再次写入同组<code>x/y</code>前必须等待前一次Vector读取结束，再次写入同组<code>z</code>前必须等待前一次MTE3搬出结束。</p><p>采用该方式时，需要注意以下事项：</p><ul><li>需要根据可用UB容量静态确定Ping/Pong缓冲区的大小、偏移和对齐方式。</li><li>尾块需要通过<code>currentLength</code>按照实际长度搬运和计算。</li><li>注意<code>asc_lock/asc_unlock</code>接口的产品支持情况；若在其他产品上开启Double Buffer，应根据同步接口支持情况，使用<code>asc_sync_notify/asc_sync_wait</code>等接口建立等价的数据依赖，不能直接照搬本节代码。</li><li>Kernel退出前需要等待已提交的异步操作完成。示例使用<code>asc_sync_pipe(PIPE_ALL)</code>排空流水。</li></ul>`,35))])])])}const k=e(r,[["render",u]]);export{T as __pageData,k as default};
